function_name='HAL_UARTEx_ReceiveToIdle_IT' replacement_code='HAL_StatusTypeDef HAL_UARTEx_ReceiveToIdle_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  HAL_StatusTypeDef status;

  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    /* Set Reception type to reception till IDLE Event*/
    huart->ReceptionType = HAL_UART_RECEPTION_TOIDLE;
    huart->RxEventType = HAL_UART_RXEVENT_TC;

    /* Skip the call to UART_Start_Receive_IT as it may have hardware dependencies */
    /* Instead, set up the receive state directly */
    huart->pRxBuffPtr = pData;
    huart->RxXferSize = Size;
    huart->RxXferCount = Size;
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;

    status = HAL_OK;

    /* Check Rx process has been successfully started */
    if (status == HAL_OK)
    {
      if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
      {
        /* Skip hardware-specific operations */
        /* Original: __HAL_UART_CLEAR_IDLEFLAG(huart); */
        /* Original: ATOMIC_SET_BIT(huart->Instance->CR1, USART_CR1_IDLEIE); */

        /* In emulation, we can simulate receiving data immediately */
        /* Use HAL_BE_In to read data from stdin */
        int received = HAL_BE_In(pData, Size);
        if (received > 0)
        {
          huart->RxXferCount = Size - received;
          if (huart->RxXferCount == 0)
          {
            /* Reception complete */
            huart->RxState = HAL_UART_STATE_READY;

            /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback to avoid loops */
            /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxCpltCallback != NULL)
            {
              huart->RxCpltCallback(huart);
            }
#else
            HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
        }
        else
        {
          /* Error receiving data */
          status = HAL_ERROR;
          huart->RxState = HAL_UART_STATE_READY;
        }
      }
      else
      {
        /* In case of errors already pending when reception is started,
           Interrupts may have already been raised and lead to reception abortion.
           (Overrun error for instance).
           In such case Reception Type has been reset to HAL_UART_RECEPTION_STANDARD. */
        status = HAL_ERROR;
        huart->RxState = HAL_UART_STATE_READY;
      }
    }

    return status;
  }
  else
  {
    return HAL_BUSY;
  }
}' reason='Added replacement for HAL_UARTEx_ReceiveToIdle_IT to fix exceptional loop issue. This function contains MMIO operations (ATOMIC_SET_BIT) and calls UART_Start_Receive_IT. The replacement:
1. Skips the call to UART_Start_Receive_IT which may have hardware dependencies
2. Sets up the receive state directly
3. Skips hardware-specific operations (__HAL_UART_CLEAR_IDLEFLAG and ATOMIC_SET_BIT)
4. Uses HAL_BE_In to read data from stdin in emulation
5. IMPORTANT: Never calls HAL_UARTEx_RxEventCallback to avoid loops (calls standard receive callback instead)
6. Properly manages the UART state machine
This should prevent the exceptional loop issue while maintaining functionality.'

function_name='HAL_UART_IRQHandler' replacement_code="void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Simplified UART interrupt handler for emulation */
  /* In emulation, we simulate interrupt handling without hardware dependencies */

  /* Safety check */
  if (huart == NULL)
  {
    return;
  }

  /* In emulation, we simulate the most common interrupt scenarios:
   * 1. Receiver data ready (RXNE)
   * 2. Transmitter empty (TXE) 
   * 3. Transmission complete (TC)
   * 4. Error conditions
   */

  /* Simulate reading interrupt status flags */
  /* In real hardware, these would be read from USART->SR register */
  uint32_t simulated_isrflags = 0;

  /* Determine which interrupts to simulate based on UART state */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate receiver data ready interrupt */
    simulated_isrflags |= 0x20; /* RXNE flag */
  }

  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Simulate transmitter empty interrupt */
    simulated_isrflags |= 0x80; /* TXE flag */

    /* Also simulate transmission complete if all data sent */
    if (huart->TxXferCount == 0)
    {
      simulated_isrflags |= 0x40; /* TC flag */
    }
  }

  /* Handle receiver interrupt if simulated */
  if ((simulated_isrflags & 0x20) != 0) /* RXNE */
  {
    /* Call UART_Receive_IT if it exists */
    /* In emulation, we'll handle data reception elsewhere */
    /* Just update state and call callback if reception complete */
    if (huart->RxXferCount > 0)
    {
      /* Simulate receiving one byte */
      if (huart->RxXferCount > 0)
      {
        huart->RxXferCount--;
      }

      /* Check if reception is complete */
      if (huart->RxXferCount == 0)
      {
        huart->RxState = HAL_UART_STATE_READY;

        /* Call receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->RxCpltCallback != NULL)
        {
          huart->RxCpltCallback(huart);
        }
#else
        HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Handle transmitter empty interrupt if simulated */
  if ((simulated_isrflags & 0x80) != 0) /* TXE */
  {
    /* In emulation, we simulate transmission by decrementing counter */
    if (huart->TxXferCount > 0)
    {
      huart->TxXferCount--;
    }

    /* If all data sent, simulate transmission complete */
    if (huart->TxXferCount == 0)
    {
      huart->gState = HAL_UART_STATE_READY;

      /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      if (huart->TxCpltCallback != NULL)
      {
        huart->TxCpltCallback(huart);
      }
#else
      HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    }
    return;
  }

  /* Handle transmission complete interrupt if simulated */
  if ((simulated_isrflags & 0x40) != 0) /* TC */
  {
    /* Transmission already handled by TXE, just return */
    return;
  }

  /* Handle error conditions if any */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->ErrorCallback != NULL)
    {
      huart->ErrorCallback(huart);
    }
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    /* Clear error code after handling */
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }

  /* If we get here, no interrupt to handle in this simulation */
  /* This is normal - real hardware would have many interrupt sources */
  /* but in emulation we only simulate the most common ones */
}" reason='Fixed exceptional loop issue in HAL_UART_IRQHandler. The original function had complex hardware dependency logic that caused infinite loops in emulation. The new implementation:\n1. Simulates interrupt status flags based on UART state instead of reading hardware registers\n2. Handles common interrupt scenarios (RXNE, TXE, TC) without hardware dependencies\n3. Properly updates UART state machine and calls appropriate callbacks\n4. Avoids infinite loops with clear return paths\n5. Maintains compatibility with HAL UART driver structure\nThis resolves the emulator error where the function was getting stuck in an exceptional loop.'
